REM What the READ ONLY user APP_R3 sees of each, and what its SELECTs run. 13 reads each sequence afterwards.
set feedback on echo on pagesize 100 linesize 160 long 80
whenever sqlerror continue
col table_name format a12
col column_name format a14
col data_default format a32
col object_owner format a10
col object_name format a12
col policy_name format a12
col pf_owner format a10
col function format a10
col name format a12
col referenced_name format a12
col referenced_type format a16
col status format a8
SELECT TABLE_NAME, COLUMN_NAME, HIDDEN_COLUMN, DATA_DEFAULT FROM ALL_TAB_COLS WHERE OWNER = 'APP_OWNER' AND VIRTUAL_COLUMN = 'YES' ORDER BY 1, 2;
SELECT OBJECT_OWNER, OBJECT_NAME, POLICY_NAME, PF_OWNER, FUNCTION, SEL FROM ALL_POLICIES ORDER BY 1, 2;
SELECT OBJECT_NAME, POLICY_NAME FROM ALL_AUDIT_POLICIES;
SELECT NAME, REFERENCED_NAME, REFERENCED_TYPE FROM ALL_DEPENDENCIES WHERE OWNER = 'APP_OWNER' AND NAME IN ('R3_OUTER', 'R3_INV_V', 'R3_BEHIND_V') ORDER BY 1, 2;
SELECT OBJECT_NAME, STATUS FROM ALL_OBJECTS WHERE OWNER = 'APP_OWNER' AND OBJECT_NAME IN ('R3_OUTER', 'R3_INNER', 'R3_INV_V') ORDER BY 1;
SELECT ID, U FROM APP_OWNER.R3_VC;
SELECT N FROM APP_OWNER.R3_VC;
SELECT SYS_NC00004$ FROM APP_OWNER.R3_FBI;
SELECT ID FROM APP_OWNER.R3_POL;
SELECT ID FROM APP_OWNER.R3_SYNPOL_S;
SELECT ID FROM R3_SYNPOL_P;
SELECT ID FROM APP_OWNER.R3_BEHIND_V;
SELECT ID FROM APP_OWNER.R3_FGA;
SELECT N FROM APP_OWNER.R3_OUTER;
SELECT N FROM APP_OWNER.R3_INV_V;
SELECT OBJECT_NAME, STATUS FROM ALL_OBJECTS WHERE OWNER = 'APP_OWNER' AND OBJECT_NAME = 'R3_INV_V';
SET TRANSACTION READ ONLY;
ALTER SESSION SET EDITION = ORA$BASE;
